void PutVarint32(std::string* dst, uint32_t v) {
  char buf[5];
  unsigned char* ptr = reinterpret_cast<unsigned char*>(buf);
  unsigned char* start = ptr;
  while (v >= 0x80) {
    *ptr++ = (v & 0x7F) | 0x80;
    v >>= 7;
  }
  *ptr++ = v & 0x7F;
  dst->append(buf, ptr - start);
}

